using namespace Eigen;
using namespace std;

// Global material properties (from MAT routine)
double G11, G12, G13, G22, G23, G33;

// GMMATD: general matrix multiply with optional transpose
// C = op(A) * op(B), where op = transpose if flag set
MatrixXd gmmatd(const MatrixXd& A, int transA, const MatrixXd& B, int transB) {
    MatrixXd At = transA ? A.transpose() : A;
    MatrixXd Bt = transB ? B.transpose() : B;
    return At * Bt;
}

// INVERD: matrix inversion (returns inverse, sets ising)
MatrixXd inverd(const MatrixXd& M, int& ising) {
    FullPivLU<MatrixXd> lu(M);
    if (!lu.isInvertible()) {
        ising = 2;
        return MatrixXd::Zero(M.rows(), M.cols());
    }
    ising = 1;
    return lu.inverse();
}

// KTRBSC - basic bending triangle
// Returns the 9 3x3 matrices (K^U) stored in A(1..81), plus Hinv (A(145..180)) and S (A(82..99))
// We'll implement IOPT=2 path which saves H-inverse and S.
struct KTRBSCResult {
    MatrixXd KU[3][3];   // KU[i][j] = 3x3 matrices, i,j = 0..2
    MatrixXd Hinv;       // 6x6
    MatrixXd S;          // 6x3
    double XSUBB, XSUBC, YSUBC;
    bool ok;
};

KTRBSCResult ktrbsc(double X1,double Y1,double Z1,
                    double X2,double Y2,double Z2,
                    double X3,double Y3,double Z3,
                    double EYE, double ANGLE, double T2,
                    double G11_,double G12_,double G13_,
                    double G22_,double G23_,double G33_) {
