int main() {
    // Test case
    double X1=0,Y1=0,Z1=0;
    double X2=1,Y2=0,Z2=0;
    double X3=0,Y3=1,Z3=0;
    double E = 200e9;
    double nu = 0.3;
    double t = 0.01;
    double I = t*t*t/12.0;  // 8.333e-8

    // Material properties for isotropic plate
    // G11 = E/(1-nu^2), G12 = nu*E/(1-nu^2), G22 = E/(1-nu^2), G33 = G = E/(2(1+nu))
    double denom = 1.0 - nu*nu;
    double G11_ = E/denom;
    double G12_ = nu*E/denom;
    double G22_ = E/denom;
    double G33_ = E/(2.0*(1.0+nu));
    double G13_ = 0.0, G23_ = 0.0;

    double ANGLE = 0.0;
    double T2 = 0.0;

    KTRBSCResult r = ktrbsc(X1,Y1,Z1, X2,Y2,Z2, X3,Y3,Z3,
                            I, ANGLE, T2,
                            G11_,G12_,G13_,G22_,G23_,G33_);

    if (!r.ok) {
        cerr << "KTRBSC failed" << endl;
        return 1;
    }

    // Now assemble the 9x9 stiffness matrix.
    // For the test case, the pivot is node 1 (A). 
    // The KTRPLT routine assembles K^U into the 9x9 matrix.
    // For a single triangle with pivot at node 1, the 9x9 matrix is just the K^U matrix
    // (since there's only one sub-triangle and it maps directly).

    // Actually, KTRPLT does more: it forms the R-matrix, loops over 3 sub-triangles,
    // and assembles. For the test case with pivot at node 1, let me trace through.

    // The R-matrix for the full triangle:
    // V1=A=(0,0,0), V2=B=(1,0,0), V3=C=(0,1,0)
    // D2 = V2-V1 = (1,0,0), D1 = V3-V1 = (0,1,0)
    // R(1,2) = |D2| = 1
    // IVECT = D2/1 = (1,0,0)
    // KVECT = IVECT x D1 = (1,0,0)x(0,1,0) = (0,0,1)
    // R(2,3) = |KVECT| = 1
    // KVECT = (0,0,1)
    // JVECT = KVECT x IVECT = (0,0,1)x(1,0,0) = (0,1,0)
    // R(1,3) = D1 . IVECT = 0
    // R(1,4) = (R(1,2)+R(1,3))/3 = 1/3
    // R(2,4) = R(2,3)/3 = 1/3

    // M = {1,2,4, 2,3,4, 3,1,4}
    // Sub-triangle 1: (1,2,4) = (A,B,centroid)
    // Sub-triangle 2: (2,3,4) = (B,C,centroid)
    // Sub-triangle 3: (3,1,4) = (C,A,centroid)

    // For each sub-triangle, KTRBSC is called with IOPT=2, and the results
    // are assembled into KSUM (9x9) and G (6x6).

    // This is quite involved. Let me implement the full KTRPLT.

    // R matrix (2x4)
    MatrixXd R = MatrixXd::Zero(2,4);
    Vector3d V1(X1,Y1,Z1), V2(X2,Y2,Z2), V3(X3,Y3,Z3);
    Vector3d D2 = V2 - V1;
    Vector3d D1 = V3 - V1;
    R(0,1) = D2.norm();
    Vector3d IVECT = D2 / R(0,1);
    Vector3d KVECT = IVECT.cross(D1);
    R(1,2) = KVECT.norm();
    KVECT = KVECT / R(1,2);
    Vector3d JVECT = KVECT.cross(IVECT);
    JVECT.normalize();
    R(0,2) = D1.dot(IVECT);
    R(0,3) = (R(0,1) + R(0,2)) / 3.0;
    R(1,3) = R(1,2) / 3.0;

    // M matrix
    int M[9] = {1,2,4, 2,3,4, 3,1,4};

    // KSUM (9x9) and G (6x6)
    MatrixXd KSUM = MatrixXd::Zero(9,9);
    MatrixXd Gmat = MatrixXd::Zero(6,6);

    double THETA = ANGLE * M_PI/180.0;
    double SINANG = sin(THETA);
    double COSANG = cos(THETA);

    // Store Hinv and S from each sub-triangle for later use
    // Actually KTRPLT uses HINV and S from the LAST call to KTRBSC (IOPT=2)
    MatrixXd Hinv_last, S_last;

    for (int J = 0; J < 3; J++) {
        int KM = 3*J;
        int SUBSCA = M[KM+0];
        int SUBSCB = M[KM+1];
        int SUBSCC = M[KM+2];

        // V = R(:,SUBSCB) - R(:,SUBSCA), VV = R(:,SUBSCC) - R(:,SUBSCA)
        Vector2d V = R.col(SUBSCB-1) - R.col(SUBSCA-1);
        Vector2d VV = R.col(SUBSCC-1) - R.col(SUBSCA-1);
        double XSUBB = V.norm();
        double U1 = V(0)/XSUBB;
        double U2 = V(1)/XSUBB;
        double XSUBC = U1*VV(0) + U2*VV(1);
        double YSUBC = U1*VV(1) - U2*VV(0);

        double SINTH = SINANG*U1 - COSANG*U2;
        double COSTH = COSANG*U1 + SINANG*U2;
        if (fabs(SINTH) < 1e-6) SINTH = 0.0;

        // Call KTRBSC with IOPT=2
        // The sub-triangle coordinates in element system:
        // A_sub = (0,0), B_sub = (XSUBB, 0), C_sub = (XSUBC, YSUBC)
        // But KTRBSC takes 3D coords. We can pass them as 2D in the element plane.
        // Actually KTRBSC computes its own I,J,K vectors from the 3D coords.
        // We need to pass coords such that XSUBB, XSUBC, YSUBC come out right.
        // Pass: A=(0,0,0), B=(XSUBB,0,0), C=(XSUBC,YSUBC,0)

        KTRBSCResult sub = ktrbsc(0,0,0, XSUBB,0,0, XSUBC,YSUBC,0,
                                  I, ANGLE, T2,
                                  G11_,G12_,G13_,G22_,G23_,G33_);
        if (!sub.ok) { cerr << "sub KTRBSC failed" << endl; return 1; }

        Hinv_last = sub.Hinv;
        S_last = sub.S;

        // T matrix (3x3)
        Matrix3d T;
        T << 1, 0, 0,
             U1, U2, 0,
             -U2, U1, 0;
        // Wait, Fortran T is column-major:
        // T(1)=1,T(2)=0,T(3)=0, T(4)=0,T(5)=U1,T(6)=U2, T(7)=0,T(8)=-U2,T(9)=U1
        // Column-major: T(1..3)=col1, T(4..6)=col2, T(7..9)=col3
        // T(1,1)=1,T(2,1)=0,T(3,1)=0
        // T(1,2)=0,T(2,2)=U1,T(3,2)=U2
        // T(1,3)=0,T(2,3)=-U2,T(3,3)=U1
        T << 1, 0, 0,
             0, U1, -U2,
             0, U2, U1;

        // For each I=1..3: T^T * KU[I-1][?] * T added to KSUM
        // Fortran: CALL GMMATD(T,3,3,1, A(27*I-8),3,3,0, TEMP9) -> TEMP9 = T^T * A(27*I-8)
        //          CALL GMMATD(TEMP9,3,3,0, T,3,3,0, PROD9) -> PROD9 = TEMP9 * T
        // A(27*I-8) is the 3x3 block at position 27*I-8. For I=1: A(19), I=2: A(46), I=3: A(73).
        // These are blocks (1,3), (2,3), (3,3) of KU9. So KU[I-1][2].
        for (int I = 0; I < 3; I++) {
            Matrix3d KUblock = sub.KU[I][2];
            Matrix3d PROD9 = T.transpose() * KUblock * T;
            // NPOINT = KM + I; NPOINT = 9*M(NPOINT) + 18
            int NPOINT = KM + I;
            int Mval = M[NPOINT];
            int zero_ptr = 9*Mval + 18;  // 1-indexed
            // KSUM(NSUBC) += PROD9(K), NSUBC = zero_ptr + K
            // zero_ptr is 1-indexed into KSUM (9x9 column-major)
            // KSUM element (zero_ptr + K - 1) in 0-indexed
            for (int K = 0; K < 9; K++) {
                int idx = zero_ptr + K - 1;  // 0-indexed
                int row = idx % 9;
                int col = idx / 9;
                KSUM(row, col) += PROD9(K % 3, K / 3);
            }
        }

        // For K=1,2: if M(KM+K) == NPIVOT (NPIVOT=1 for node A)
        int NPIVOT = 1;  // pivot at node A
        for (int K = 1; K <= 2; K++) {
            int NPOINT = KM + K;
            if (M[NPOINT] != NPIVOT) continue;
            // CALL GMMATD(T,3,3,1, A(36*K-35),3,3,0, TEMP9) -> T^T * A(36*K-35)
            // A(36*K-35): K=1 -> A(1), K=2 -> A(37). These are blocks (1,1) and (2,2).
            Matrix3d KUblock = sub.KU[K-1][K-1];
            Matrix3d PROD9 = T.transpose() * KUblock * T;
            int zero_ptr = 9*NPIVOT - 9;  // 1-indexed
            for (int I = 0; I < 9; I++) {
                int idx = zero_ptr + I;  // 0-indexed
                int row = idx % 9;
                int col = idx / 9;
                KSUM(row, col) += PROD9(I % 3, I / 3);
            }

            // CALL GMMATD(T,3,3,1, A(18*K-8),3,3,0, TEMP9) -> T^T * A(18*K-8)
            // A(18*K-8): K=1 -> A(10), K=2 -> A(28). These are blocks (1,2) and (2,1).
            Matrix3d KUblock2 = sub.KU[K-1][(K==1)?1:0];
            Matrix3d PROD9b = T.transpose() * KUblock2 * T;
            int NPOINT2 = KM + 3 - K;
            int Mval2 = M[NPOINT2];
            int zero_ptr2 = 9*Mval2 - 9;  // 1-indexed
            for (int I = 0; I < 9; I++) {
                int idx = zero_ptr2 + I;  // 0-indexed
                int row = idx % 9;
                int col = idx / 9;
                KSUM(row, col) += PROD9b(I % 3, I / 3);
            }
        }

        // Form HQ (2x6)
        double TEMP1 = XSUBB - XSUBC;
        double TEMP2 = YSUBC*YSUBC;
        double L1 = sqrt(XSUBC*XSUBC + TEMP2);
        double L2 = sqrt(TEMP1*TEMP1 + TEMP2);
        double S1 = XSUBC/L1;
        double S2 = TEMP1/L2;
        double C1 = YSUBC/L1;
        double C2 = YSUBC/L2;
        double X1_ = XSUBC/2.0;
        double Y1_ = YSUBC/2.0;
        double X2_ = (XSUBB+XSUBC)/2.0;
        double Y2_ = Y1_;

        MatrixXd HQ(2,6);
        HQ(0,0) = -XSUBC*C1;
        HQ(0,1) = X1_*S1 - Y1_*C1;
        HQ(0,2) = 2.0*Y1_*S1;
        HQ(0,3) = -3.0*X1_*X1_*C1;
        HQ(0,4) = Y1_*(2.0*X1_*S1 - Y1_*C1);
        HQ(0,5) = 3.0*Y1_*Y1_*S1;
