        HQ(1,1) = X2_*S2 + Y2_*C2;
        HQ(1,2) = 2.0*Y2_*S2;
        HQ(1,3) = 3.0*X2_*X2_*C2;
        HQ(1,4) = Y2_*(2.0*X2_*S2 + Y2_*C2);
        HQ(1,5) = 3.0*Y2_*Y2_*S2;

