        MatrixXd HABC = -(PROD12 * sub.S);
        HABC(0,0) += S1;
        HABC(0,1) += C1;
        HABC(1,0) += S2;
        HABC(1,1) -= C2;

        // Now HABC is 2x3, but we need to split into H_psi_B and H_psi_C
        // Fortran stores HABC(1..6) as the 2x3, then HABC(7..18) as PROD12 rearranged.
        // HABC(7..12) = PROD12(1,2,3,7,8,9) -> PROD12 rows 1-2, cols 1-3
        // HABC(13..18) = PROD12(4,5,6,10,11,12) -> PROD12 rows 1-2, cols 4-6

        // Build full HABC as 2x6: [H_psi_A | H_psi_B | H_psi_C]? No.
        // Actually HABC(1..6) is H_psi_A (2x3), HABC(7..12) is H_psi_B (2x3), HABC(13..18) is H_psi_C (2x3).
        MatrixXd HpsiA = HABC;  // 2x3
        MatrixXd HpsiB(2,3), HpsiC(2,3);
        HpsiB << PROD12(0,0), PROD12(0,1), PROD12(0,2),
                 PROD12(1,0), PROD12(1,1), PROD12(1,2);
        HpsiC << PROD12(0,3), PROD12(0,4), PROD12(0,5),
                 PROD12(1,3), PROD12(1,4), PROD12(1,5);

