        MatrixXd Hpsi[3] = {HpsiA, HpsiB, HpsiC};

        for (int I = 0; I < 3; I++) {
            // Transform H_sub_I: TEMP9 = Hpsi[I] * T (2x3)
            MatrixXd TEMP9 = Hpsi[I] * T;

            int NPOINT = KM + I;
            int Mval = M[NPOINT];
            int zero_ptr = 9*Mval - 9;  // 1-indexed

            // J=1 (J index 0): row1->row1, row2->row2
            // J=2 (J index 1): row1->row2, row2->row3
            // J=3 (J index 2): row1->row3, row2->row1
            if (J == 0) {
                // NPOINT stays, add 6 elements
                for (int K = 0; K < 6; K++) {
                    int idx = zero_ptr + K;  // 0-indexed
                    int row = idx % 6;
                    int col = idx / 6;
                    Gmat(row, col) += TEMP9(K % 2, K / 2);
                }
            } else if (J == 1) {
