                int np = zero_ptr + 3;
                for (int K = 0; K < 6; K++) {
                    int idx = np + K;
                    int row = idx % 6;
                    int col = idx / 6;
                    Gmat(row, col) += TEMP9(K % 2, K / 2);
                }
            } else {
