                // G(NPOINT+7) += TEMP9(1), G(NPOINT+8) += TEMP9(2), G(NPOINT+9) += TEMP9(3)
                // G(NPOINT+1) += TEMP9(4), G(NPOINT+2) += TEMP9(5), G(NPOINT+3) += TEMP9(6)
                // NPOINT is 1-indexed
                int np = zero_ptr;
