    // E(11)=E(5,2)=IVECT(1), E(14)=E(2,3)=IVECT(2), E(17)=E(5,3)=IVECT(3)
    // E(12)=E(6,2)=JVECT(1), E(15)=E(3,3)=JVECT(2), E(18)=E(6,3)=JVECT(3)

    E6 = MatrixXd::Zero(6,3);
