    E6(3,0) = KVECT(1);  // E(4)
    E6(0,1) = KVECT(2);  // E(7)
    E6(4,1) = IVECT(0);  // E(11)
    E6(5,1) = JVECT(0);  // E(12)
    E6(1,2) = IVECT(1);  // E(14)
    E6(2,2) = JVECT(1);  // E(15)
    E6(4,2) = IVECT(2);  // E(17)
    E6(5,2) = JVECT(2);  // E(18)

