    MatrixXd TITE = E6;

    // Now solve for K^E_IJ
    // (TERM_I) = G4^-1 * G_I, I=NPIVOT=1
    // G4 is G(28..36) = Gmat rows 4-6, cols 1-3 (column-major: G(28)=G(4,1),...)
    // G(28..36) column-major: G(28)=G(4,1),G(29)=G(5,1),G(30)=G(6,1),G(31)=G(4,2),G(32)=G(5,2),G(33)=G(6,2),G(34)=G(4,3),G(35)=G(5,3),G(36)=G(6,3)
    Matrix3d G4 = Gmat.block(3,0,3,3);

    int ising;
    Matrix3d G4inv = inverd(G4, ising);
    if (ising == 2) { cerr << "G4 singular" << endl; return 1; }

    // G(9*NPIVOT-8) = G(1) for NPIVOT=1 -> G(1..9) = Gmat rows 1-3, cols 1-3
    Matrix3d G1 = Gmat.block(0,0,3,3);

    // PROD9 = G4inv * G1 (TERM_I)
    Matrix3d PROD9 = G4inv * G1;

    // TEMP9 = PROD9^T * KSUM(55..63) = PROD9^T * K44
    // KSUM(55..63) column-major: KSUM(55)=KSUM(1,7),... 
    // KSUM is 9x9. KSUM(55..63): 55 = (col-1)*9+row -> col=7,row=1. So KSUM(55..63) = KSUM rows 1-9, col 7? No.
    // 55 = 6*9+1 -> col=7, row=1. 63 = 6*9+9 -> col=7, row=9. So KSUM(55..63) = column 7 of KSUM.
    // Hmm, but KSUM(55) should be a 3x3 block. Let me reconsider.
    // Actually KSUM(55..63) is 9 elements = 3x3 block. In column-major 9x9, elements 55-63 span col 7 rows 1-9. That's not a 3x3 block.
